let cashHorizon=28,driverView='forecast';
function cashCategory(e){let text=String(e.description||'').toLowerCase();if(e.type==='inventory'||e.type==='supplier'||/inventory|stock|supplier|采购|库存|供应商/.test(text))return'Inventory & supplier payments';if(/payroll|salary|wage|社保|薪酬|工资/.test(text))return'Salaries';if(/rent|租金|房租/.test(text))return'Rent';if(/market|advert|campaign|marketing|营销|市场/.test(text))return'Marketing';if(/utility|electric|water|cloud|utilities|水电|云服务/.test(text))return'Utilities & services';if(/admin|office|行政|办公/.test(text))return'Administration';if(e.type==='receipt')return'Customer receipts';return'Other / unclassified'}
function weeklyCashData(x,n){let count=Math.max(1,Math.ceil(n/7)),labels=Array.from({length:count+1},(_,i)=>{let d=new Date(today());d.setDate(d.getDate()+Math.min(n,i*7));return d.toLocaleDateString(undefined,{month:'short',day:'numeric'})}),balance=Array.from({length:count+1},(_,i)=>x.path[Math.min(n,i*7)]),inflow=Array(count).fill(0),outflow=Array(count).fill(0),inCats={},outCats={};for(const e of x.events){if(e.day>n)continue;let day=Math.max(1,e.day),w=Math.min(count,Math.ceil(day/7))-1;if(w<0)continue;let amount=Math.abs(e.impact)*(e.inFlow?1+(+x.d.salesGrowth||0)/100:1+(+x.d.cost||0)/100),cat=cashCategory(e);if(e.inFlow){inflow[w]+=amount;inCats[cat]??=Array(count).fill(0);inCats[cat][w]+=amount}else{outflow[w]+=amount;outCats[cat]??=Array(count).fill(0);outCats[cat][w]+=amount}}return{count,labels,balance,inflow,outflow,inCats,outCats}}
