 if(outflows.length>=2||suppliers.length)strategies.push({id:'operations',icon:'⚙',title:'Operational Optimization',objective:'Test a modest outflow reduction and supplier-payment timing adjustment against the same cash model.',actions:[outflows.length?'Reduce modeled dated operating outflows by 5%.':'Operating cost inputs unavailable.',suppliers.length?'Shift recorded supplier / inventory payments by 7 days for timing analysis.':'Supplier timing cannot be tested from current records.'],drivers:['recorded outflows'].concat(suppliers.length?['supplier / inventory payment dates']:[]),params:{sales:0,cost:outflows.length?-5:0,receiptDelay:0,supplierDelay:suppliers.length?7:0},available:outflows.length>0});
 if(receipts.length&&outflows.length&&x.liquidity!=='High Risk'&&(x.growthState==='Observed growth'||x.liquidity==='Stable'))strategies.push({id:'guarded-growth',icon:'↗',title:'Growth with Liquidity Guardrails',objective:'Test higher recorded receipts with the associated operating-cost assumption while monitoring the reserve.',actions:['Increase modeled receipts by 5% as a sensitivity assumption.','Increase modeled outflows by 2% to represent incremental operating cost; validate the assumption.'],drivers:['dated receipt amounts','dated operating outflows','cash reserve'],params:{sales:5,cost:2,receiptDelay:0,supplierDelay:0},available:true});
 return strategies;
