 const generationMarkup='<div class="sc-ai-generation"><style>.sc-ai-generation{margin:16px 0;padding:16px;border:1px solid #dfe8eb;border-radius:14px;background:#fbfdfd}.sc-ai-generation .sc-gen-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.sc-ai-generation h3{margin:4px 0}.sc-ai-generation p{color:#6d7e8d;font-size:12px;line-height:1.5}.sc-ai-generation .sc-gen-context{display:grid;grid-template-columns:1fr 1fr;gap:12px}.sc-ai-generation .sc-gen-box{padding:12px;border-radius:10px;background:#f1f5f6}.sc-ai-generation .sc-gen-box p,.sc-ai-generation .sc-gen-box small{font-size:11px;color:#667988;line-height:1.5}.sc-ai-generation .sc-gen-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:12px 0}.sc-ai-generation .sc-gen-card{border:1px solid #e0e7ea;border-radius:11px;padding:13px;background:white;display:flex;flex-direction:column;gap:7px}.sc-ai-generation .sc-gen-card h4{margin:0}.sc-ai-generation .sc-gen-card p,.sc-ai-generation .sc-gen-card small{font-size:11px;color:#657786}.sc-ai-generation .sc-gen-card ul{margin:0;padding-left:17px;font-size:11px;line-height:1.5}.sc-ai-generation .sc-gen-metric{padding:8px;background:#f3f7f8;border-radius:8px;font-size:11px}.sc-ai-generation .sc-gen-card button{margin-top:auto}@media(max-width:800px){.sc-ai-generation .sc-gen-cards{grid-template-columns:1fr 1fr}}@media(max-width:600px){.sc-ai-generation .sc-gen-context,.sc-ai-generation .sc-gen-cards{grid-template-columns:1fr}.sc-ai-generation .sc-gen-head{align-items:flex-start;flex-direction:column}}</style><div class="sc-gen-head"><div><span class="sc-badge">DETERMINISTIC PROTOTYPE</span><h3>AI Scenario Generation</h3><p>Options adapt to recorded cash drivers, liquidity state and supported variables. No live LLM reasoning is connected.</p></div><button type="button" class="sc-run" data-sc-generate '+(base?'':'disabled')+'>'+(st.generated?'Refresh Strategies':'Generate Scenario Strategies')+'</button></div><div class="sc-gen-context"><div class="sc-gen-box"><b>Drivers used by strategy generation</b><p>'+driverRows.length+' dated driver(s) from the evidence list above; direct cash effects, not inferred root causes.</p></div><div class="sc-gen-box"><b>Business state &amp; variable relationships</b><p>Liquidity <b>'+esc(x.liquidity)+'</b> · Data confidence '+confidence+'</p><p>'+(receiptEvents.length?'Receipts → inflow · Collection timing → cash date · ':'')+(inventoryEvents.length?'Procurement → outflow · ':'')+(expenseEvents.length?'Operating expense → outflow · ':'')+(x.safe!=null?'Cash ↔ reserve threshold.':'Reserve threshold unavailable.')+'</p><small>Only applicable relationships with available records are used.</small></div></div><p><b>Reasoning:</b> assess state → identify variables → combine possible actions → check constraints → simulate and reassess. '+esc(x.liquidity==='High Risk'?'A modeled reserve breach prioritizes liquidity recovery.':x.liquidity==='Watch'?'The narrow buffer prioritizes cash protection.':x.liquidity==='Stable'?'No breach is supported; cost efficiency and bounded receipt assumptions can be compared.':'State needs current cash and reserve inputs.')+'</p>'+(st.generated?(strategies.length?'<div class="sc-gen-cards">'+strategies.map(function(a){var preview=simulate(a.cfg),change=base&&preview?preview.min-base.min:null;return '<article class="sc-gen-card"><span class="sc-badge">ALTERNATIVE STRATEGY</span><h4>'+esc(a.name)+'</h4><p>'+esc(a.objective)+'</p><small><b>Drivers:</b> '+esc(a.drivers.join(' · '))+'</small><ul>'+a.actions.map(v=>'<li>'+esc(v)+'</li>').join('')+'</ul><div class="sc-gen-metric"><b>Same-model preview:</b> '+(preview?money(preview.min)+' minimum · '+(preview.breach>0?'breach day '+preview.breach:'no modeled breach'):'Insufficient Data')+'<br><b>Change vs baseline:</b> '+(change==null?'Insufficient Data':(change>=0?'+':'')+money(change))+'</div><details><summary>Assumptions &amp; potential risks</summary><p>'+esc(a.risk)+' Preview is illustrative; source records are unchanged.</p></details><button type="button" class="sc-run" data-sc-run-generated="'+a.id+'">Run Simulation</button></article>'}).join('')+'</div>':'<div class="sc-empty">Needs More Data · no strategies can be quantified from current dated inputs.</div>'):'<div class="sc-empty">Generate strategies to see options supported by current data. Strategies requiring unavailable inputs are omitted.</div>')+'</div>';
 const recommendation=base&&baselineGap>0&&collect&&collect.min>base.min&&receiptEvents.length?'Prioritize validating customer collection dates first. It improves modeled timing without assuming lender availability; confirm customer commitments and remaining liquidity risk.':base&&baselineGap>0&&stock&&stock.min>base.min&&inventoryEvents.length?'Review procurement timing and essential stock requirements. The simulated cash improvement depends on changing dated supplier outflows and must be checked against contracts and stock needs.':base&&baselineGap>0?'A cash shortfall is modeled, but available strategies lack enough verified cost, feasibility or repayment evidence for a recommendation. Gather those inputs before deciding.':'No funding or growth strategy is supported by the current evidence. Use the comparison as a what-if view and validate costs, demand and execution constraints.';
 const barRow=(id,label,val,min,max,step,unit,desc)=>'<label class="sc-control"><span>'+label+' <b id="sc-out-'+id+'">'+val+unit+'</b></span><input type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+val+'" data-sc-var="'+id+'"><small>'+desc+'</small></label>',numberRow=(id,label,val,desc)=>'<label class="sc-control"><span>'+label+'</span><input type="number" min="0" step="500" value="'+val+'" data-sc-var="'+id+'"><small>'+desc+'</small></label>';
