function go(page){let old={forecast:'dso-cash',cash:'dso-cash',expenses:'dso-risk','dso-memory':'dso-scenario'};page=old[page]||page;focusTarget='';if(!pages[page]||!E(page))return;let h='#'+page;if(location.hash!==h)history.pushState({page},'',h);renderPage(page,true)}
